window.PS = window.PS || {};
PS.gg = {
  stand: 'September 2026 (einschließlich der Änderungen von 2024 und 2025)',
  quelle: 'https://www.gesetze-im-internet.de/gg/',
  praeambel: 'Im Bewußtsein seiner Verantwortung vor Gott und den Menschen, von dem Willen beseelt, als gleichberechtigtes Glied in einem vereinten Europa dem Frieden der Welt zu dienen, hat sich das Deutsche Volk kraft seiner verfassunggebenden Gewalt dieses Grundgesetz gegeben. Die Deutschen in den Ländern Baden-Württemberg, Bayern, Berlin, Brandenburg, Bremen, Hamburg, Hessen, Mecklenburg-Vorpommern, Niedersachsen, Nordrhein-Westfalen, Rheinland-Pfalz, Saarland, Sachsen, Sachsen-Anhalt, Schleswig-Holstein und Thüringen haben in freier Selbstbestimmung die Einheit und Freiheit Deutschlands vollendet. Damit gilt dieses Grundgesetz für das gesamte Deutsche Volk.',
  abschnitte: [
    {
      nr: 'I', titel: 'Die Grundrechte', bereich: 'Art. 1–19',
      intro: 'Die Grundrechte stehen bewusst am Anfang: Nach den Erfahrungen der NS-Diktatur sollte klar sein, dass der Staat für den Menschen da ist und nicht umgekehrt. Sie binden Gesetzgebung, Verwaltung und Rechtsprechung unmittelbar. Manche gelten für alle Menschen (Jedermann-Rechte), manche nur für Deutsche (Bürgerrechte, z. B. Art. 8, 9, 11, 12).',
      arts: [
        { n: '1', t: 'Schutz der Menschenwürde, Menschenrechte, Grundrechtsbindung', s: 'Die Würde des Menschen ist unantastbar; der Staat muss sie achten und schützen. Deutschland bekennt sich zu unverletzlichen und unveräußerlichen Menschenrechten. Die folgenden Grundrechte binden Gesetzgebung, vollziehende Gewalt und Rechtsprechung als unmittelbar geltendes Recht.', z: 'Die Würde des Menschen ist unantastbar. Sie zu achten und zu schützen ist Verpflichtung aller staatlichen Gewalt.' },
        { n: '2', t: 'Freie Entfaltung der Persönlichkeit, Recht auf Leben, körperliche Unversehrtheit, Freiheit der Person', s: 'Jede Person darf ihre Persönlichkeit frei entfalten (allgemeine Handlungsfreiheit), soweit sie nicht die Rechte anderer verletzt und nicht gegen die verfassungsmäßige Ordnung oder das Sittengesetz verstößt. Zusammen mit Art. 1 leitet das Bundesverfassungsgericht daraus das allgemeine Persönlichkeitsrecht ab, etwa das Recht auf informationelle Selbstbestimmung. Geschützt sind außerdem Leben, körperliche Unversehrtheit und die Freiheit der Person; Eingriffe sind nur auf Grund eines Gesetzes erlaubt.', z: 'Jeder hat das Recht auf die freie Entfaltung seiner Persönlichkeit, soweit er nicht die Rechte anderer verletzt und nicht gegen die verfassungsmäßige Ordnung oder das Sittengesetz verstößt.' },
        { n: '3', t: 'Gleichheit vor dem Gesetz', s: 'Alle Menschen sind vor dem Gesetz gleich. Männer und Frauen sind gleichberechtigt; seit 1994 muss der Staat die tatsächliche Gleichberechtigung auch fördern. Niemand darf wegen Geschlecht, Abstammung, Rasse, Sprache, Heimat und Herkunft, Glauben, religiöser oder politischer Anschauungen benachteiligt oder bevorzugt werden. Seit 1994 darf außerdem niemand wegen einer Behinderung benachteiligt werden.', z: 'Alle Menschen sind vor dem Gesetz gleich.' },
        { n: '4', t: 'Glaubens-, Gewissens- und Bekenntnisfreiheit', s: 'Geschützt ist die Freiheit, einen Glauben oder eine Weltanschauung zu haben – oder keine –, sie zu bekennen und ungestört auszuüben. Niemand darf gegen sein Gewissen zum Kriegsdienst mit der Waffe gezwungen werden.', z: 'Die Freiheit des Glaubens, des Gewissens und die Freiheit des religiösen und weltanschaulichen Bekenntnisses sind unverletzlich.' },
        { n: '5', t: 'Meinungs-, Informations-, Presse-, Rundfunk-, Kunst- und Wissenschaftsfreiheit', s: 'Jede Person darf ihre Meinung in Wort, Schrift und Bild frei äußern und verbreiten und sich aus allgemein zugänglichen Quellen informieren. Presse-, Rundfunk- und Filmfreiheit sind gewährleistet; eine Zensur findet nicht statt. Grenzen ziehen die allgemeinen Gesetze, der Jugendschutz und das Recht der persönlichen Ehre. Kunst und Wissenschaft, Forschung und Lehre sind frei; die Freiheit der Lehre entbindet nicht von der Treue zur Verfassung.', z: 'Jeder hat das Recht, seine Meinung in Wort, Schrift und Bild frei zu äußern und zu verbreiten und sich aus allgemein zugänglichen Quellen ungehindert zu unterrichten.' },
        { n: '6', t: 'Ehe, Familie, Kinder', s: 'Ehe und Familie stehen unter dem besonderen Schutz des Staates. Pflege und Erziehung der Kinder sind das natürliche Recht und die Pflicht der Eltern; die staatliche Gemeinschaft wacht darüber (staatliches Wächteramt). Gegen den Willen der Eltern dürfen Kinder nur auf Grund eines Gesetzes von der Familie getrennt werden, wenn die Eltern versagen oder die Kinder zu verwahrlosen drohen. Mütter haben Anspruch auf Schutz und Fürsorge; nichteheliche Kinder sind ehelichen gleichzustellen.', z: 'Ehe und Familie stehen unter dem besonderen Schutze der staatlichen Ordnung.' },
        { n: '7', t: 'Schulwesen', s: 'Das gesamte Schulwesen steht unter der Aufsicht des Staates. Religionsunterricht ist an öffentlichen Schulen ordentliches Lehrfach (außer an bekenntnisfreien Schulen); die Erziehungsberechtigten entscheiden über die Teilnahme. Privatschulen dürfen unter bestimmten Voraussetzungen gegründet werden; sie dürfen keine Sonderung nach den Besitzverhältnissen der Eltern fördern.' },
        { n: '8', t: 'Versammlungsfreiheit', s: 'Alle Deutschen dürfen sich ohne Anmeldung oder Erlaubnis friedlich und ohne Waffen versammeln. Für Versammlungen unter freiem Himmel kann das Recht durch Gesetz beschränkt werden – etwa durch die Anmeldepflicht nach den Versammlungsgesetzen des Bundes und der Länder.', z: 'Alle Deutschen haben das Recht, sich ohne Anmeldung oder Erlaubnis friedlich und ohne Waffen zu versammeln.' },
        { n: '9', t: 'Vereinigungs- und Koalitionsfreiheit', s: 'Alle Deutschen dürfen Vereine und Gesellschaften gründen. Vereinigungen, deren Zwecke den Strafgesetzen zuwiderlaufen oder die sich gegen die verfassungsmäßige Ordnung oder die Völkerverständigung richten, sind verboten. Jede Person und jeder Beruf darf Vereinigungen zur Wahrung der Arbeits- und Wirtschaftsbedingungen bilden – Grundlage für Gewerkschaften, Arbeitgeberverbände, Tarifautonomie und Streikrecht.' },
        { n: '10', t: 'Brief-, Post- und Fernmeldegeheimnis', s: 'Briefe, Post und Telekommunikation sind vertraulich. Beschränkungen sind nur auf Grund eines Gesetzes zulässig. Dient eine Beschränkung dem Schutz der freiheitlichen demokratischen Grundordnung, kann die Benachrichtigung der Betroffenen unterbleiben; dann kontrolliert ein vom Parlament bestelltes Gremium (G 10-Kommission).', z: 'Das Briefgeheimnis sowie das Post- und Fernmeldegeheimnis sind unverletzlich.' },
        { n: '11', t: 'Freizügigkeit', s: 'Alle Deutschen dürfen sich im ganzen Bundesgebiet frei bewegen und niederlassen. Einschränkungen sind nur durch Gesetz und nur aus bestimmten Gründen zulässig, etwa zur Abwehr einer Seuchengefahr, bei Naturkatastrophen oder zur Abwehr einer drohenden Gefahr für den Bestand des Bundes.' },
        { n: '12', t: 'Berufsfreiheit, Verbot der Zwangsarbeit', s: 'Alle Deutschen dürfen Beruf, Arbeitsplatz und Ausbildungsstätte frei wählen; die Berufsausübung kann durch Gesetz geregelt werden. Niemand darf zu einer bestimmten Arbeit gezwungen werden, außer im Rahmen einer herkömmlichen, für alle gleichen öffentlichen Dienstleistungspflicht. Zwangsarbeit ist nur bei einer gerichtlich angeordneten Freiheitsentziehung zulässig.', z: 'Alle Deutschen haben das Recht, Beruf, Arbeitsplatz und Ausbildungsstätte frei zu wählen.' },
        { n: '12a', t: 'Wehr- und Dienstpflichten', s: 'Männer können ab 18 Jahren zum Dienst in den Streitkräften, im Bundesgrenzschutz (heute Bundespolizei) oder in einem Zivilschutzverband verpflichtet werden; wer den Kriegsdienst aus Gewissensgründen verweigert, kann zu einem Ersatzdienst verpflichtet werden. Im Verteidigungsfall sind weitere Dienstverpflichtungen möglich. Frauen können im Verteidigungsfall zu zivilen Diensten im Sanitäts- und Heilwesen herangezogen werden; zum Dienst mit der Waffe dürfen sie auf keinen Fall verpflichtet werden.' },
        { n: '13', t: 'Unverletzlichkeit der Wohnung', s: 'Die Wohnung ist unverletzlich. Durchsuchungen darf grundsätzlich nur ein Richter anordnen, bei Gefahr im Verzug auch andere gesetzlich bestimmte Stellen. Seit 1998 erlaubt das Grundgesetz unter engen Voraussetzungen das Abhören von Wohnungen zur Verfolgung besonders schwerer Straftaten („Großer Lauschangriff“); das Parlament wird darüber jährlich unterrichtet.', z: 'Die Wohnung ist unverletzlich.' },
        { n: '14', t: 'Eigentum, Erbrecht, Enteignung', s: 'Eigentum und Erbrecht werden gewährleistet; Inhalt und Schranken bestimmen die Gesetze. Eigentum verpflichtet und soll zugleich dem Wohl der Allgemeinheit dienen (Sozialbindung). Eine Enteignung ist nur zum Wohl der Allgemeinheit, nur durch oder auf Grund eines Gesetzes und nur gegen Entschädigung zulässig.', z: 'Eigentum verpflichtet. Sein Gebrauch soll zugleich dem Wohle der Allgemeinheit dienen.' },
        { n: '15', t: 'Vergesellschaftung', s: 'Grund und Boden, Naturschätze und Produktionsmittel können durch Gesetz, das Art und Ausmaß der Entschädigung regelt, in Gemeineigentum überführt werden. Die Vorschrift wurde bisher nie angewendet; sie spielte aber etwa in der Berliner Debatte über die Vergesellschaftung großer Wohnungsunternehmen eine Rolle.' },
        { n: '16', t: 'Ausbürgerung, Auslieferung', s: 'Die deutsche Staatsangehörigkeit darf nicht entzogen werden. Ein Verlust darf nur auf Grund eines Gesetzes eintreten und gegen den Willen der Person nur, wenn sie dadurch nicht staatenlos wird. Deutsche dürfen grundsätzlich nicht ins Ausland ausgeliefert werden; Ausnahmen sind für EU-Staaten und internationale Gerichte möglich, wenn rechtsstaatliche Grundsätze gewahrt sind.' },
        { n: '16a', t: 'Asylrecht', s: 'Politisch Verfolgte genießen Asylrecht. Seit dem Asylkompromiss von 1993 kann sich darauf nicht berufen, wer aus einem EU-Staat oder einem anderen sicheren Drittstaat einreist. Für Menschen aus sicheren Herkunftsstaaten wird vermutet, dass sie nicht verfolgt werden. In der Praxis wird Schutz heute überwiegend nach der Genfer Flüchtlingskonvention und dem EU-Recht gewährt.', z: 'Politisch Verfolgte genießen Asylrecht.' },
        { n: '17', t: 'Petitionsrecht', s: 'Jede Person kann sich allein oder gemeinsam mit anderen schriftlich mit Bitten oder Beschwerden an die zuständigen Stellen und an die Volksvertretungen wenden. Die Petition muss geprüft und beschieden werden.', z: 'Jedermann hat das Recht, sich einzeln oder in Gemeinschaft mit anderen schriftlich mit Bitten oder Beschwerden an die zuständigen Stellen und an die Volksvertretung zu wenden.' },
        { n: '17a', t: 'Einschränkung von Grundrechten im Wehr- und Ersatzdienst', s: 'Für Angehörige der Streitkräfte und des Ersatzdienstes können Gesetze bestimmte Grundrechte einschränken, etwa die freie Meinungsäußerung, die Versammlungsfreiheit oder das gemeinschaftliche Petitionsrecht. Gesetze zur Verteidigung und zum Schutz der Zivilbevölkerung können Freizügigkeit und Unverletzlichkeit der Wohnung beschränken.' },
        { n: '18', t: 'Verwirkung von Grundrechten', s: 'Wer die Meinungs-, Presse-, Lehr-, Versammlungs- oder Vereinigungsfreiheit, das Brief- und Fernmeldegeheimnis, das Eigentum oder das Asylrecht zum Kampf gegen die freiheitliche demokratische Grundordnung missbraucht, verwirkt diese Grundrechte. Darüber entscheidet allein das Bundesverfassungsgericht. Bisher war kein Antrag erfolgreich.' },
        { n: '19', t: 'Einschränkung von Grundrechten, Rechtsweggarantie', s: 'Schränkt ein Gesetz ein Grundrecht ein, muss es allgemein gelten und das Grundrecht ausdrücklich nennen (Zitiergebot). Kein Grundrecht darf in seinem Wesensgehalt angetastet werden. Grundrechte gelten auch für inländische juristische Personen, soweit sie ihrem Wesen nach passen. Wer durch die öffentliche Gewalt in seinen Rechten verletzt wird, kann vor Gericht klagen (Rechtsweggarantie).', z: 'In keinem Falle darf ein Grundrecht in seinem Wesensgehalt angetastet werden.' }
      ]
    },
    {
      nr: 'II', titel: 'Der Bund und die Länder', bereich: 'Art. 20–37',
      intro: 'Dieser Abschnitt legt die Grundprinzipien des Staates fest – Demokratie, Rechtsstaat, Sozialstaat, Bundesstaat, Republik – und regelt das Verhältnis von Bund und Ländern, Parteien, Europa und Völkerrecht.',
      arts: [
        { n: '20', t: 'Verfassungsgrundsätze, Widerstandsrecht', s: 'Deutschland ist ein demokratischer und sozialer Bundesstaat. Alle Staatsgewalt geht vom Volke aus; sie wird in Wahlen und Abstimmungen sowie durch besondere Organe der Gesetzgebung, der vollziehenden Gewalt und der Rechtsprechung ausgeübt (Gewaltenteilung). Die Gesetzgebung ist an die verfassungsmäßige Ordnung gebunden, Verwaltung und Gerichte an Gesetz und Recht (Rechtsstaat). Gegen jeden, der diese Ordnung beseitigen will, haben alle Deutschen das Recht zum Widerstand, wenn andere Abhilfe nicht möglich ist.', z: 'Die Bundesrepublik Deutschland ist ein demokratischer und sozialer Bundesstaat.' },
        { n: '20a', t: 'Schutz der natürlichen Lebensgrundlagen und der Tiere', s: 'Staatsziel seit 1994 (Umweltschutz) und 2002 (Tierschutz): Der Staat schützt auch in Verantwortung für die künftigen Generationen die natürlichen Lebensgrundlagen und die Tiere. Im Klimabeschluss von 2021 leitete das Bundesverfassungsgericht daraus auch eine Pflicht zum Klimaschutz ab.', z: 'Der Staat schützt auch in Verantwortung für die künftigen Generationen die natürlichen Lebensgrundlagen und die Tiere im Rahmen der verfassungsmäßigen Ordnung durch die Gesetzgebung und nach Maßgabe von Gesetz und Recht durch die vollziehende Gewalt und die Rechtsprechung.' },
        { n: '21', t: 'Parteien', s: 'Parteien wirken bei der politischen Willensbildung mit. Ihre Gründung ist frei, ihre innere Ordnung muss demokratisch sein, und sie müssen über Herkunft und Verwendung ihrer Mittel und ihres Vermögens öffentlich Rechenschaft geben. Parteien, die darauf ausgehen, die freiheitliche demokratische Grundordnung zu beeinträchtigen oder zu beseitigen, sind verfassungswidrig – darüber entscheidet nur das Bundesverfassungsgericht. Seit 2017 können verfassungsfeindliche Parteien auch von der staatlichen Finanzierung ausgeschlossen werden.', z: 'Die Parteien wirken bei der politischen Willensbildung des Volkes mit.' },
        { n: '22', t: 'Hauptstadt, Bundesflagge', s: 'Hauptstadt ist Berlin; die Repräsentation des Gesamtstaates dort ist Aufgabe des Bundes (seit 2006 im Grundgesetz). Die Bundesflagge ist schwarz-rot-gold.', z: 'Die Bundesflagge ist schwarz-rot-gold.' },
        { n: '23', t: 'Europäische Union', s: 'Deutschland wirkt an der Entwicklung einer Europäischen Union mit, die demokratischen, rechtsstaatlichen, sozialen und föderativen Grundsätzen und dem Grundsatz der Subsidiarität verpflichtet ist. Dazu kann der Bund Hoheitsrechte übertragen; die Grenzen der Ewigkeitsklausel gelten auch dabei. Bundestag und Länder (über den Bundesrat) wirken in EU-Angelegenheiten mit. Bis 1990 regelte Art. 23 den Beitritt anderer Teile Deutschlands – auf dieser Grundlage trat die DDR am 3. Oktober 1990 bei.' },
        { n: '24', t: 'Übertragung von Hoheitsrechten, kollektive Sicherheit', s: 'Der Bund kann Hoheitsrechte auf zwischenstaatliche Einrichtungen übertragen. Zur Wahrung des Friedens kann er sich einem System gegenseitiger kollektiver Sicherheit einordnen – Grundlage für die Mitgliedschaft in UNO und NATO und für Auslandseinsätze der Bundeswehr in diesem Rahmen.' },
        { n: '25', t: 'Vorrang des Völkerrechts', s: 'Die allgemeinen Regeln des Völkerrechts sind Bestandteil des Bundesrechts. Sie gehen den Gesetzen vor und erzeugen unmittelbar Rechte und Pflichten für die Bewohner des Bundesgebietes.' },
        { n: '26', t: 'Verbot des Angriffskrieges, Kriegswaffenkontrolle', s: 'Handlungen, die das friedliche Zusammenleben der Völker stören sollen, insbesondere die Vorbereitung eines Angriffskrieges, sind verfassungswidrig und unter Strafe zu stellen. Kriegswaffen dürfen nur mit Genehmigung der Bundesregierung hergestellt, befördert und in Verkehr gebracht werden (Kriegswaffenkontrollgesetz).', z: 'Handlungen, die geeignet sind und in der Absicht vorgenommen werden, das friedliche Zusammenleben der Völker zu stören, insbesondere die Führung eines Angriffskrieges vorzubereiten, sind verfassungswidrig.' },
        { n: '27', t: 'Handelsflotte', s: 'Alle deutschen Kauffahrteischiffe (Handelsschiffe) bilden eine einheitliche Handelsflotte.' },
        { n: '28', t: 'Verfassungsordnung der Länder, kommunale Selbstverwaltung', s: 'Die Ordnung in den Ländern muss den Grundsätzen des republikanischen, demokratischen und sozialen Rechtsstaates entsprechen (Homogenitätsgebot). In Ländern, Kreisen und Gemeinden muss das Volk eine gewählte Vertretung haben; bei Kommunalwahlen dürfen auch Bürgerinnen und Bürger anderer EU-Staaten wählen. Gemeinden haben das Recht, alle Angelegenheiten der örtlichen Gemeinschaft in eigener Verantwortung zu regeln.' },
        { n: '29', t: 'Neugliederung des Bundesgebietes', s: 'Das Bundesgebiet kann neu gegliedert werden, damit die Länder nach Größe und Leistungsfähigkeit ihre Aufgaben wirksam erfüllen können. Dafür ist ein Bundesgesetz nötig, das in den betroffenen Gebieten durch Volksentscheid bestätigt werden muss – einer der wenigen Fälle, in denen das Grundgesetz eine Volksabstimmung vorsieht.' },
        { n: '30', t: 'Zuständigkeit der Länder', s: 'Die Ausübung staatlicher Befugnisse und die Erfüllung staatlicher Aufgaben ist Sache der Länder, soweit das Grundgesetz keine andere Regelung trifft oder zulässt. Der Bund braucht also für jede Zuständigkeit eine Grundlage im Grundgesetz.' },
        { n: '31', t: 'Vorrang des Bundesrechts', s: 'Widerspricht eine Regel des Landesrechts einer gültigen Regel des Bundesrechts, setzt sich das Bundesrecht durch.', z: 'Bundesrecht bricht Landesrecht.' },
        { n: '32', t: 'Auswärtige Beziehungen', s: 'Die Pflege der Beziehungen zu auswärtigen Staaten ist Sache des Bundes. Vor Verträgen, die ein Land besonders berühren, ist es zu hören. In ihren eigenen Zuständigkeiten dürfen die Länder mit Zustimmung der Bundesregierung Verträge mit anderen Staaten schließen.' },
        { n: '33', t: 'Staatsbürgerliche Gleichheit, öffentlicher Dienst', s: 'Alle Deutschen haben in jedem Land die gleichen staatsbürgerlichen Rechte und Pflichten und nach Eignung, Befähigung und fachlicher Leistung gleichen Zugang zu jedem öffentlichen Amt (Bestenauslese). Das religiöse Bekenntnis darf dabei keine Rolle spielen. Hoheitliche Aufgaben werden in der Regel von Beamtinnen und Beamten wahrgenommen; ihr Recht richtet sich nach den hergebrachten Grundsätzen des Berufsbeamtentums.' },
        { n: '34', t: 'Haftung bei Amtspflichtverletzung', s: 'Verletzt jemand in Ausübung eines öffentlichen Amtes seine Pflichten gegenüber einem Dritten, haftet grundsätzlich der Staat oder die Körperschaft, in deren Dienst die Person steht (Amtshaftung). Bei Vorsatz oder grober Fahrlässigkeit ist ein Rückgriff auf die Person möglich. Für Schadensersatzansprüche ist der ordentliche Rechtsweg offen.' },
        { n: '35', t: 'Rechts- und Amtshilfe, Katastrophenhilfe', s: 'Alle Behörden des Bundes und der Länder leisten sich gegenseitig Rechts- und Amtshilfe. Bei Naturkatastrophen oder besonders schweren Unglücksfällen kann ein Land Polizeikräfte anderer Länder, die Bundespolizei und die Streitkräfte anfordern; bei länderübergreifenden Gefahren kann die Bundesregierung sie einsetzen.' },
        { n: '36', t: 'Personal der Bundesbehörden', s: 'Bei den obersten Bundesbehörden sollen Beamte aus allen Ländern in angemessenem Verhältnis beschäftigt werden. Die Wehrgesetze berücksichtigen auch die Gliederung des Bundes in Länder.' },
        { n: '37', t: 'Bundeszwang', s: 'Erfüllt ein Land seine Pflichten gegenüber dem Bund nicht, kann die Bundesregierung mit Zustimmung des Bundesrates die nötigen Maßnahmen treffen, um es dazu anzuhalten; sie erhält dafür ein Weisungsrecht gegenüber allen Ländern. Der Bundeszwang wurde bisher nie angewendet.' }
      ]
    },
    {
      nr: 'III', titel: 'Der Bundestag', bereich: 'Art. 38–49',
      intro: 'Der Bundestag ist das einzige unmittelbar vom Volk gewählte Verfassungsorgan des Bundes. Hier werden Wahl, Wahlperiode, Organisation, Ausschüsse und die Rechte der Abgeordneten geregelt.',
      arts: [
        { n: '38', t: 'Wahl, Stellung der Abgeordneten', s: 'Die Abgeordneten werden in allgemeiner, unmittelbarer, freier, gleicher und geheimer Wahl gewählt. Sie sind Vertreter des ganzen Volkes, an Aufträge und Weisungen nicht gebunden und nur ihrem Gewissen unterworfen (freies Mandat). Wahlberechtigt ist, wer das 18. Lebensjahr vollendet hat; wählbar ist, wer volljährig ist. Einzelheiten regelt das Bundeswahlgesetz.', z: 'Die Abgeordneten des Deutschen Bundestages werden in allgemeiner, unmittelbarer, freier, gleicher und geheimer Wahl gewählt.' },
        { n: '39', t: 'Wahlperiode, Zusammentritt, Einberufung', s: 'Der Bundestag wird auf vier Jahre gewählt. Die Neuwahl findet frühestens 46 und spätestens 48 Monate nach Beginn der Wahlperiode statt, nach einer Auflösung innerhalb von 60 Tagen. Der neue Bundestag tritt spätestens am 30. Tag nach der Wahl zusammen. Er bestimmt Schluss und Wiederbeginn seiner Sitzungen selbst.' },
        { n: '40', t: 'Präsidium, Geschäftsordnung', s: 'Der Bundestag wählt seine Präsidentin oder seinen Präsidenten, die Stellvertreter und die Schriftführer und gibt sich eine Geschäftsordnung. Die Präsidentin übt das Hausrecht und die Polizeigewalt im Gebäude des Bundestages aus; ohne ihre Genehmigung darf dort nicht durchsucht oder beschlagnahmt werden.' },
        { n: '41', t: 'Wahlprüfung', s: 'Über die Gültigkeit einer Wahl entscheidet zunächst der Bundestag selbst; dagegen ist Beschwerde zum Bundesverfassungsgericht möglich. Wegen zahlreicher Pannen musste die Bundestagswahl 2021 in Teilen Berlins im Februar 2024 wiederholt werden.' },
        { n: '42', t: 'Öffentlichkeit, Mehrheitsprinzip', s: 'Der Bundestag verhandelt öffentlich; die Öffentlichkeit kann mit Zwei-Drittel-Mehrheit ausgeschlossen werden. Beschlüsse werden grundsätzlich mit der Mehrheit der abgegebenen Stimmen gefasst. Wahrheitsgetreue Berichte über öffentliche Sitzungen bleiben straffrei.' },
        { n: '43', t: 'Zitier-, Zutritts- und Anhörungsrecht', s: 'Bundestag und Ausschüsse können die Anwesenheit jedes Regierungsmitglieds verlangen (Zitierrecht). Mitglieder des Bundesrates und der Bundesregierung haben Zutritt zu allen Sitzungen und müssen jederzeit gehört werden.' },
        { n: '44', t: 'Untersuchungsausschüsse', s: 'Der Bundestag hat das Recht und auf Antrag eines Viertels seiner Mitglieder die Pflicht, einen Untersuchungsausschuss einzusetzen (Minderheitenrecht). Der Ausschuss erhebt Beweise in öffentlicher Verhandlung; die Vorschriften über den Strafprozess gelten sinngemäß. Gerichte und Behörden müssen Rechts- und Amtshilfe leisten.' },
        { n: '45', t: 'Ausschuss für Angelegenheiten der Europäischen Union', s: 'Der Bundestag bestellt einen Europaausschuss. Er kann ihn ermächtigen, die Rechte des Bundestages gegenüber der Bundesregierung in EU-Angelegenheiten wahrzunehmen.' },
        { n: '45a', t: 'Ausschüsse für Auswärtiges und Verteidigung', s: 'Der Bundestag muss einen Ausschuss für auswärtige Angelegenheiten und einen Verteidigungsausschuss bilden. Der Verteidigungsausschuss hat auch die Rechte eines Untersuchungsausschusses.' },
        { n: '45b', t: 'Wehrbeauftragte', s: 'Zum Schutz der Grundrechte der Soldatinnen und Soldaten und als Hilfsorgan des Bundestages bei der parlamentarischen Kontrolle der Bundeswehr wird eine Wehrbeauftragte oder ein Wehrbeauftragter berufen. Jede Soldatin und jeder Soldat kann sich direkt an sie wenden.' },
        { n: '45c', t: 'Petitionsausschuss', s: 'Der Bundestag bestellt einen Petitionsausschuss, der die nach Art. 17 an den Bundestag gerichteten Bitten und Beschwerden behandelt.' },
        { n: '45d', t: 'Parlamentarisches Kontrollgremium', s: 'Ein besonderes Gremium des Bundestages kontrolliert die Nachrichtendienste des Bundes – Bundesnachrichtendienst, Bundesamt für Verfassungsschutz und Militärischen Abschirmdienst.' },
        { n: '46', t: 'Indemnität und Immunität', s: 'Abgeordnete dürfen wegen einer Abstimmung oder einer Äußerung im Bundestag oder seinen Ausschüssen nicht gerichtlich oder dienstlich verfolgt werden – außer bei verleumderischen Beleidigungen (Indemnität). Wegen einer Straftat dürfen sie nur mit Genehmigung des Bundestages belangt oder verhaftet werden, außer sie werden bei der Tat oder im Laufe des folgenden Tages festgenommen (Immunität).' },
        { n: '47', t: 'Zeugnisverweigerungsrecht', s: 'Abgeordnete dürfen die Aussage über Personen verweigern, die ihnen in ihrer Eigenschaft als Abgeordnete Tatsachen anvertraut haben, und über diese Tatsachen selbst. Insoweit ist auch die Beschlagnahme von Schriftstücken unzulässig.' },
        { n: '48', t: 'Rechte der Abgeordneten', s: 'Wer sich um einen Sitz im Bundestag bewirbt, hat Anspruch auf Urlaub zur Wahlvorbereitung. Niemand darf gehindert werden, ein Mandat anzunehmen; eine Kündigung deswegen ist unzulässig. Abgeordnete haben Anspruch auf eine angemessene, ihre Unabhängigkeit sichernde Entschädigung und auf freie Benutzung der staatlichen Verkehrsmittel.' },
        { n: '49', t: '(aufgehoben)', s: 'Der Artikel regelte früher die Stellung der Ausschüsse zwischen zwei Wahlperioden und wurde 1976 aufgehoben.', rep: true }
      ]
    },
    {
      nr: 'IV', titel: 'Der Bundesrat', bereich: 'Art. 50–53',
      intro: 'Der Bundesrat ist das Organ, über das die Länder an der Politik des Bundes mitwirken.',
      arts: [
        { n: '50', t: 'Aufgabe', s: 'Durch den Bundesrat wirken die Länder bei der Gesetzgebung und Verwaltung des Bundes und in Angelegenheiten der Europäischen Union mit.', z: 'Durch den Bundesrat wirken die Länder bei der Gesetzgebung und Verwaltung des Bundes und in Angelegenheiten der Europäischen Union mit.' },
        { n: '51', t: 'Zusammensetzung', s: 'Der Bundesrat besteht aus Mitgliedern der Landesregierungen, die diese bestellen und abberufen. Jedes Land hat mindestens drei Stimmen; Länder mit mehr als zwei Millionen Einwohnern haben vier, mit mehr als sechs Millionen fünf, mit mehr als sieben Millionen sechs Stimmen. Die Stimmen eines Landes können nur einheitlich abgegeben werden.' },
        { n: '52', t: 'Präsident, Beschlussfassung, Europakammer', s: 'Der Bundesrat wählt seine Präsidentin oder seinen Präsidenten für ein Jahr. Beschlüsse brauchen mindestens die Mehrheit seiner Stimmen, also 35 von 69 – Enthaltungen wirken deshalb wie Nein-Stimmen. Für EU-Angelegenheiten kann eine Europakammer gebildet werden.' },
        { n: '53', t: 'Teilnahme der Bundesregierung', s: 'Mitglieder der Bundesregierung haben das Recht und auf Verlangen die Pflicht, an den Verhandlungen des Bundesrates und seiner Ausschüsse teilzunehmen. Die Bundesregierung muss den Bundesrat über die Führung der Geschäfte auf dem Laufenden halten.' }
      ]
    },
    {
      nr: 'IVa', titel: 'Gemeinsamer Ausschuss', bereich: 'Art. 53a',
      intro: 'Der Gemeinsame Ausschuss ist eine Vorsorge für den Verteidigungsfall.',
      arts: [
        { n: '53a', t: 'Gemeinsamer Ausschuss', s: 'Der Ausschuss besteht zu zwei Dritteln aus Abgeordneten des Bundestages (nach Stärke der Fraktionen, sie dürfen nicht der Bundesregierung angehören) und zu einem Drittel aus Mitgliedern des Bundesrates, je eines pro Land. Die Bundesregierung muss ihn über ihre Planungen für den Verteidigungsfall unterrichten. Im Verteidigungsfall kann er als Notparlament an die Stelle von Bundestag und Bundesrat treten (Art. 115e).' }
      ]
    },
    {
      nr: 'V', titel: 'Der Bundespräsident', bereich: 'Art. 54–61',
      intro: 'Der Bundespräsident ist Staatsoberhaupt. Seine Befugnisse sind – anders als die des Reichspräsidenten der Weimarer Republik – bewusst begrenzt.',
      arts: [
        { n: '54', t: 'Wahl durch die Bundesversammlung', s: 'Der Bundespräsident wird ohne Aussprache von der Bundesversammlung gewählt. Wählbar ist jede und jeder Deutsche mit Wahlrecht zum Bundestag, der das 40. Lebensjahr vollendet hat. Die Amtszeit dauert fünf Jahre; eine anschließende Wiederwahl ist nur einmal zulässig. Die Bundesversammlung besteht aus den Mitgliedern des Bundestages und ebenso vielen von den Landtagen gewählten Mitgliedern. Gewählt ist, wer die Mehrheit der Mitglieder erhält; im dritten Wahlgang genügt die relative Mehrheit.' },
        { n: '55', t: 'Unvereinbarkeiten', s: 'Der Bundespräsident darf weder der Regierung noch einer gesetzgebenden Körperschaft des Bundes oder eines Landes angehören. Er darf kein anderes besoldetes Amt, kein Gewerbe und keinen Beruf ausüben und keinem Aufsichtsrat eines Unternehmens angehören.' },
        { n: '56', t: 'Amtseid', s: 'Bei seinem Amtsantritt leistet der Bundespräsident vor den versammelten Mitgliedern von Bundestag und Bundesrat den Amtseid. Die religiöse Beteuerung am Ende kann entfallen. Denselben Eid leisten Kanzler und Minister (Art. 64).', z: 'Ich schwöre, daß ich meine Kraft dem Wohle des deutschen Volkes widmen, seinen Nutzen mehren, Schaden von ihm wenden, das Grundgesetz und die Gesetze des Bundes wahren und verteidigen, meine Pflichten gewissenhaft erfüllen und Gerechtigkeit gegen jedermann üben werde. So wahr mir Gott helfe.' },
        { n: '57', t: 'Vertretung', s: 'Ist der Bundespräsident verhindert oder endet sein Amt vorzeitig, nimmt die Präsidentin oder der Präsident des Bundesrates seine Befugnisse wahr.' },
        { n: '58', t: 'Gegenzeichnung', s: 'Anordnungen und Verfügungen des Bundespräsidenten brauchen zu ihrer Gültigkeit die Gegenzeichnung durch den Bundeskanzler oder den zuständigen Bundesminister – dieser übernimmt damit die politische Verantwortung. Ausgenommen sind die Ernennung und Entlassung des Kanzlers, die Auflösung des Bundestages nach Art. 63 und das Ersuchen um geschäftsführende Weiterführung nach Art. 69.' },
        { n: '59', t: 'Völkerrechtliche Vertretung', s: 'Der Bundespräsident vertritt den Bund völkerrechtlich, schließt im Namen des Bundes Verträge mit auswärtigen Staaten und beglaubigt und empfängt die Gesandten (Botschafter). Verträge über die politischen Beziehungen oder über Gegenstände der Bundesgesetzgebung brauchen die Zustimmung der gesetzgebenden Körperschaften in Form eines Bundesgesetzes.' },
        { n: '59a', t: '(aufgehoben)', s: 'Der Artikel regelte früher die Feststellung des Verteidigungsfalls; seit 1968 steht dies in Art. 115a.', rep: true },
        { n: '60', t: 'Ernennung von Beamten, Richtern und Soldaten, Begnadigung', s: 'Der Bundespräsident ernennt und entlässt die Bundesrichter, die Bundesbeamten, die Offiziere und Unteroffiziere, soweit gesetzlich nichts anderes bestimmt ist. Er übt im Einzelfall für den Bund das Begnadigungsrecht aus.' },
        { n: '61', t: 'Präsidentenanklage', s: 'Bundestag oder Bundesrat können den Bundespräsidenten wegen vorsätzlicher Verletzung des Grundgesetzes oder eines Bundesgesetzes vor dem Bundesverfassungsgericht anklagen; nötig sind zwei Drittel der Mitglieder des Bundestages oder der Stimmen des Bundesrates. Stellt das Gericht die Verletzung fest, kann es ihn des Amtes für verlustig erklären.' }
      ]
    },
    {
      nr: 'VI', titel: 'Die Bundesregierung', bereich: 'Art. 62–69',
      intro: 'Die Bundesregierung ist vom Vertrauen des Bundestages abhängig. Das konstruktive Misstrauensvotum soll – anders als in der Weimarer Republik – stabile Regierungen sichern.',
      arts: [
        { n: '62', t: 'Zusammensetzung', s: 'Die Bundesregierung besteht aus dem Bundeskanzler und den Bundesministern.', z: 'Die Bundesregierung besteht aus dem Bundeskanzler und aus den Bundesministern.' },
        { n: '63', t: 'Wahl des Bundeskanzlers', s: 'Der Bundespräsident schlägt dem Bundestag eine Person vor, die ohne Aussprache gewählt wird; nötig ist die Mehrheit der Mitglieder (Kanzlermehrheit). Scheitert die Wahl, kann der Bundestag binnen 14 Tagen mit Kanzlermehrheit eine andere Person wählen. Gelingt auch das nicht, findet sofort ein weiterer Wahlgang statt, in dem die meisten Stimmen genügen. Erreicht die gewählte Person dabei nur die relative Mehrheit, muss der Bundespräsident sie binnen sieben Tagen ernennen oder den Bundestag auflösen.' },
        { n: '64', t: 'Ernennung und Entlassung der Minister', s: 'Die Bundesminister werden auf Vorschlag des Bundeskanzlers vom Bundespräsidenten ernannt und entlassen. Kanzler und Minister leisten bei Amtsantritt vor dem Bundestag den Amtseid nach Art. 56.' },
        { n: '65', t: 'Richtlinien-, Ressort- und Kollegialprinzip', s: 'Der Bundeskanzler bestimmt die Richtlinien der Politik und trägt dafür die Verantwortung. Innerhalb dieser Richtlinien leitet jeder Minister seinen Geschäftsbereich selbstständig und unter eigener Verantwortung. Über Meinungsverschiedenheiten zwischen Ministern entscheidet die Bundesregierung als Kollegium.', z: 'Der Bundeskanzler bestimmt die Richtlinien der Politik und trägt dafür die Verantwortung.' },
        { n: '65a', t: 'Befehls- und Kommandogewalt', s: 'Der Bundesminister der Verteidigung hat die Befehls- und Kommandogewalt über die Streitkräfte. Mit der Verkündung des Verteidigungsfalls geht sie auf den Bundeskanzler über (Art. 115b).' },
        { n: '66', t: 'Unvereinbarkeiten', s: 'Kanzler und Minister dürfen kein anderes besoldetes Amt, kein Gewerbe und keinen Beruf ausüben und ohne Zustimmung des Bundestages weder der Leitung noch dem Aufsichtsrat eines auf Erwerb gerichteten Unternehmens angehören.' },
        { n: '67', t: 'Konstruktives Misstrauensvotum', s: 'Der Bundestag kann dem Kanzler das Misstrauen nur aussprechen, indem er mit der Mehrheit seiner Mitglieder einen Nachfolger wählt. Der Bundespräsident muss dem Ersuchen folgen. Zwischen Antrag und Wahl müssen 48 Stunden liegen. Erfolgreich war ein Misstrauensvotum bisher nur einmal: 1982 wurde Helmut Kohl auf diesem Weg Nachfolger von Helmut Schmidt.', z: 'Der Bundestag kann dem Bundeskanzler das Mißtrauen nur dadurch aussprechen, daß er mit der Mehrheit seiner Mitglieder einen Nachfolger wählt und den Bundespräsidenten ersucht, den Bundeskanzler zu entlassen.' },
        { n: '68', t: 'Vertrauensfrage', s: 'Findet ein Antrag des Kanzlers, ihm das Vertrauen auszusprechen, nicht die Mehrheit der Mitglieder des Bundestages, kann der Bundespräsident auf Vorschlag des Kanzlers binnen 21 Tagen den Bundestag auflösen – es sei denn, der Bundestag wählt vorher einen anderen Kanzler. Zuletzt stellte Olaf Scholz im Dezember 2024 die Vertrauensfrage; nach der Auflösung wurde am 23. Februar 2025 neu gewählt.' },
        { n: '69', t: 'Stellvertreter, Ende der Amtszeit', s: 'Der Kanzler ernennt einen Minister zu seinem Stellvertreter (Vizekanzler). Das Amt des Kanzlers und der Minister endet mit dem Zusammentritt eines neuen Bundestages; auf Ersuchen führen sie die Geschäfte bis zur Ernennung der Nachfolger weiter (geschäftsführende Regierung).' }
      ]
    },
    {
      nr: 'VII', titel: 'Die Gesetzgebung des Bundes', bereich: 'Art. 70–82',
      intro: 'Hier ist festgelegt, wer für welche Gesetze zuständig ist, wie ein Bundesgesetz entsteht und wie das Grundgesetz geändert werden kann.',
      arts: [
        { n: '70', t: 'Gesetzgebung von Bund und Ländern', s: 'Die Länder haben das Recht der Gesetzgebung, soweit das Grundgesetz nicht dem Bund Gesetzgebungsbefugnisse verleiht. Die Abgrenzung richtet sich nach den Vorschriften über die ausschließliche und die konkurrierende Gesetzgebung.' },
        { n: '71', t: 'Ausschließliche Gesetzgebung des Bundes', s: 'In diesen Bereichen haben die Länder die Befugnis zur Gesetzgebung nur, wenn und soweit sie in einem Bundesgesetz ausdrücklich dazu ermächtigt werden.' },
        { n: '72', t: 'Konkurrierende Gesetzgebung', s: 'Die Länder dürfen Gesetze erlassen, solange und soweit der Bund nicht selbst gehandelt hat. In einigen Bereichen darf der Bund nur, wenn eine bundeseinheitliche Regelung zur Herstellung gleichwertiger Lebensverhältnisse oder zur Wahrung der Rechts- oder Wirtschaftseinheit erforderlich ist. In anderen Bereichen dürfen die Länder von Bundesgesetzen abweichen; dann gilt jeweils das spätere Gesetz (Abweichungsgesetzgebung).' },
        { n: '73', t: 'Gegenstände der ausschließlichen Gesetzgebung', s: 'Katalog der Bundeszuständigkeiten, unter anderem: auswärtige Angelegenheiten und Verteidigung, Staatsangehörigkeit, Freizügigkeit, Pass- und Meldewesen, Währung und Geld, Maße und Gewichte, Zölle und Außenhandel, Luftverkehr, Eisenbahnen des Bundes, Post und Telekommunikation, gewerblicher Rechtsschutz und Urheberrecht, Zusammenarbeit der Kriminalpolizei, Abwehr des internationalen Terrorismus durch das Bundeskriminalamt, Waffen- und Sprengstoffrecht sowie Kernenergie.' },
        { n: '74', t: 'Gegenstände der konkurrierenden Gesetzgebung', s: 'Umfangreicher Katalog, unter anderem: bürgerliches Recht, Strafrecht, Gerichtsverfassung und gerichtliches Verfahren, Personenstandswesen, Vereinsrecht, Aufenthaltsrecht, öffentliche Fürsorge, Recht der Wirtschaft, Arbeitsrecht und Sozialversicherung, Ausbildungsbeihilfen, Lebensmittelrecht, Straßenverkehr, Abfallwirtschaft, Luftreinhaltung und Lärmbekämpfung, Staatshaftung, Naturschutz, Raumordnung, Wasserhaushalt sowie Hochschulzulassung und -abschlüsse.' },
        { n: '74a', t: '(aufgehoben)', s: 'Der Artikel regelte die Besoldung und Versorgung im öffentlichen Dienst; er wurde mit der Föderalismusreform 2006 aufgehoben.', rep: true },
        { n: '75', t: '(aufgehoben)', s: 'Der Artikel regelte die Rahmengesetzgebung des Bundes; sie wurde mit der Föderalismusreform 2006 abgeschafft.', rep: true },
        { n: '76', t: 'Gesetzesvorlagen', s: 'Gesetzesvorlagen werden von der Bundesregierung, aus der Mitte des Bundestages oder vom Bundesrat eingebracht. Vorlagen der Bundesregierung gehen zuerst an den Bundesrat, der in der Regel binnen sechs Wochen Stellung nehmen kann. Vorlagen des Bundesrates werden über die Bundesregierung an den Bundestag weitergeleitet.' },
        { n: '77', t: 'Gesetzgebungsverfahren', s: 'Bundesgesetze werden vom Bundestag beschlossen und dem Bundesrat zugeleitet. Der Bundesrat kann binnen drei Wochen den Vermittlungsausschuss anrufen. Bei Zustimmungsgesetzen entscheidet er über die Zustimmung. Bei Einspruchsgesetzen kann er Einspruch einlegen; den kann der Bundestag mit der Mehrheit seiner Mitglieder zurückweisen – bei einem Einspruch mit Zwei-Drittel-Mehrheit mit zwei Dritteln der abgegebenen Stimmen, mindestens aber der Mehrheit seiner Mitglieder.' },
        { n: '78', t: 'Zustandekommen der Bundesgesetze', s: 'Ein vom Bundestag beschlossenes Gesetz kommt zustande, wenn der Bundesrat zustimmt, den Vermittlungsausschuss nicht anruft, keinen Einspruch einlegt, den Einspruch zurücknimmt oder wenn der Bundestag den Einspruch überstimmt.' },
        { n: '79', t: 'Änderung des Grundgesetzes', s: 'Das Grundgesetz kann nur durch ein Gesetz geändert werden, das seinen Wortlaut ausdrücklich ändert oder ergänzt. Nötig sind zwei Drittel der Mitglieder des Bundestages und zwei Drittel der Stimmen des Bundesrates. Unantastbar sind die Gliederung des Bundes in Länder, die grundsätzliche Mitwirkung der Länder bei der Gesetzgebung und die Grundsätze der Artikel 1 und 20 (Ewigkeitsklausel). Seit 1949 wurde das Grundgesetz mehr als 60-mal geändert.', z: 'Eine Änderung dieses Grundgesetzes, durch welche die Gliederung des Bundes in Länder, die grundsätzliche Mitwirkung der Länder bei der Gesetzgebung oder die in den Artikeln 1 und 20 niedergelegten Grundsätze berührt werden, ist unzulässig.' },
        { n: '80', t: 'Rechtsverordnungen', s: 'Durch Gesetz können die Bundesregierung, ein Bundesminister oder die Landesregierungen ermächtigt werden, Rechtsverordnungen zu erlassen. Inhalt, Zweck und Ausmaß der Ermächtigung müssen im Gesetz bestimmt sein, und die Rechtsgrundlage ist in der Verordnung anzugeben. Viele Verordnungen brauchen die Zustimmung des Bundesrates.' },
        { n: '80a', t: 'Spannungsfall', s: 'Bestimmte Vorschriften für die Verteidigung dürfen bereits vor dem Verteidigungsfall angewendet werden, wenn der Bundestag den Spannungsfall festgestellt oder der Anwendung besonders zugestimmt hat – jeweils mit Zwei-Drittel-Mehrheit der abgegebenen Stimmen.' },
        { n: '81', t: 'Gesetzgebungsnotstand', s: 'Wird der Bundestag nach einer gescheiterten Vertrauensfrage nicht aufgelöst und lehnt er eine dringliche Gesetzesvorlage der Regierung ab, kann der Bundespräsident auf Antrag der Bundesregierung mit Zustimmung des Bundesrates den Gesetzgebungsnotstand erklären. Das Gesetz kommt dann mit Zustimmung des Bundesrates zustande. Das Verfahren wurde nie angewendet.' },
        { n: '82', t: 'Ausfertigung, Verkündung, Inkrafttreten', s: 'Die nach dem Grundgesetz zustande gekommenen Gesetze werden nach Gegenzeichnung vom Bundespräsidenten ausgefertigt und im Bundesgesetzblatt verkündet. Jedes Gesetz soll den Tag des Inkrafttretens bestimmen; fehlt eine Bestimmung, tritt es mit dem vierzehnten Tag nach Ausgabe des Bundesgesetzblattes in Kraft.' }
      ]
    },
    {
      nr: 'VIII', titel: 'Die Ausführung der Bundesgesetze und die Bundesverwaltung', bereich: 'Art. 83–91',
      intro: 'Der Bund macht viele Gesetze, ausgeführt werden sie aber meist von den Ländern. Dieser Abschnitt regelt, wer welche Verwaltung führt – einschließlich Bundeswehr, Bahn, Post und Autobahnen.',
      arts: [
        { n: '83', t: 'Ausführung durch die Länder', s: 'Die Länder führen die Bundesgesetze grundsätzlich als eigene Angelegenheit aus, soweit das Grundgesetz nichts anderes bestimmt oder zulässt.' },
        { n: '84', t: 'Landeseigenverwaltung, Bundesaufsicht', s: 'Führen die Länder Bundesgesetze als eigene Angelegenheit aus, regeln sie die Einrichtung der Behörden und das Verfahren grundsätzlich selbst. Die Bundesregierung übt die Aufsicht darüber aus, dass die Gesetze rechtmäßig ausgeführt werden. Durch Bundesgesetz dürfen Gemeinden keine Aufgaben übertragen werden.' },
        { n: '85', t: 'Bundesauftragsverwaltung', s: 'Führen die Länder Bundesgesetze im Auftrag des Bundes aus, unterstehen sie auch den Weisungen der zuständigen obersten Bundesbehörden; die Aufsicht erstreckt sich auf Gesetz- und Zweckmäßigkeit. Beispiele sind die Bundesstraßen und Teile der Atomaufsicht.' },
        { n: '86', t: 'Bundeseigene Verwaltung', s: 'Führt der Bund Gesetze durch eigene Behörden oder bundesunmittelbare Körperschaften aus, erlässt die Bundesregierung die allgemeinen Verwaltungsvorschriften und regelt die Einrichtung der Behörden.' },
        { n: '87', t: 'Gegenstände der bundeseigenen Verwaltung', s: 'In bundeseigener Verwaltung werden unter anderem der Auswärtige Dienst, die Bundesfinanzverwaltung und die Verwaltung der Bundeswasserstraßen geführt. Der Bund kann Bundespolizeibehörden sowie Zentralstellen für das polizeiliche Auskunfts- und Nachrichtenwesen, die Kriminalpolizei und den Verfassungsschutz einrichten. Sozialversicherungsträger, die über ein Land hinausreichen, sind bundesunmittelbare Körperschaften.' },
        { n: '87a', t: 'Streitkräfte', s: 'Der Bund stellt Streitkräfte zur Verteidigung auf; ihre Stärke und Organisation müssen sich aus dem Haushaltsplan ergeben. Außer zur Verteidigung dürfen sie nur eingesetzt werden, soweit das Grundgesetz es ausdrücklich zulässt. Seit 2022 erlaubt Absatz 1a ein Sondervermögen für die Bundeswehr mit eigener Kreditermächtigung von bis zu 100 Milliarden Euro. Im Inneren ist ein Einsatz nur in engen Grenzen möglich, etwa im Spannungs- oder Verteidigungsfall oder zur Abwehr einer drohenden Gefahr für die freiheitliche demokratische Grundordnung.' },
        { n: '87b', t: 'Bundeswehrverwaltung', s: 'Die Bundeswehrverwaltung wird in bundeseigener Verwaltung mit eigenem Verwaltungsunterbau geführt. Sie ist für das Personalwesen und die Deckung des Sachbedarfs der Streitkräfte zuständig.' },
        { n: '87c', t: 'Kernenergie', s: 'Gesetze über Erzeugung und Nutzung der Kernenergie können bestimmen, dass sie von den Ländern im Auftrag des Bundes ausgeführt werden.' },
        { n: '87d', t: 'Luftverkehrsverwaltung', s: 'Die Luftverkehrsverwaltung wird in Bundesverwaltung geführt. Aufgaben der Flugsicherung können auch ausländischen Flugsicherungsorganisationen übertragen werden, die nach EU-Recht zugelassen sind.' },
        { n: '87e', t: 'Eisenbahnen des Bundes', s: 'Die Eisenbahnverkehrsverwaltung für die Eisenbahnen des Bundes wird in bundeseigener Verwaltung geführt. Die Eisenbahnen des Bundes werden als Wirtschaftsunternehmen in privatrechtlicher Form geführt; die Mehrheit an Unternehmen, die das Schienennetz bauen, unterhalten oder betreiben, muss beim Bund bleiben. Der Bund gewährleistet, dass beim Ausbau des Netzes dem Wohl der Allgemeinheit Rechnung getragen wird.' },
        { n: '87f', t: 'Post und Telekommunikation', s: 'Der Bund gewährleistet im Bereich des Postwesens und der Telekommunikation flächendeckend angemessene und ausreichende Dienstleistungen. Sie werden als privatwirtschaftliche Tätigkeiten durch die aus der Deutschen Bundespost hervorgegangenen Unternehmen und durch andere private Anbieter erbracht.' },
        { n: '88', t: 'Bundesbank, Europäische Zentralbank', s: 'Der Bund errichtet eine Währungs- und Notenbank als Bundesbank. Ihre Aufgaben und Befugnisse können im Rahmen der EU der Europäischen Zentralbank übertragen werden, die unabhängig ist und dem vorrangigen Ziel der Preisstabilität verpflichtet ist.' },
        { n: '89', t: 'Bundeswasserstraßen', s: 'Der Bund ist Eigentümer der bisherigen Reichswasserstraßen. Er verwaltet die Bundeswasserstraßen durch eigene Behörden und nimmt die staatlichen Aufgaben der Binnenschifffahrt wahr.' },
        { n: '90', t: 'Bundesautobahnen und Bundesstraßen', s: 'Der Bund bleibt Eigentümer der Bundesautobahnen und sonstigen Bundesstraßen des Fernverkehrs; das Eigentum ist unveräußerlich. Die Autobahnen werden seit 2021 vom Bund selbst verwaltet (Autobahn GmbH des Bundes); eine Beteiligung Privater an der Gesellschaft ist ausgeschlossen. Die übrigen Bundesstraßen verwalten die Länder im Auftrag des Bundes.' },
        { n: '91', t: 'Innerer Notstand', s: 'Zur Abwehr einer drohenden Gefahr für den Bestand oder die freiheitliche demokratische Grundordnung des Bundes oder eines Landes kann ein Land Polizeikräfte anderer Länder und der Bundespolizei anfordern. Ist das betroffene Land dazu nicht bereit oder in der Lage, kann die Bundesregierung die Polizei in diesem und in anderen Ländern ihren Weisungen unterstellen.' }
      ]
    },
    {
      nr: 'VIIIa', titel: 'Gemeinschaftsaufgaben, Verwaltungszusammenarbeit', bereich: 'Art. 91a–91e',
      intro: 'In einigen Bereichen arbeiten Bund und Länder ausdrücklich zusammen und teilen sich die Kosten.',
      arts: [
        { n: '91a', t: 'Gemeinschaftsaufgaben', s: 'Der Bund wirkt bei der Verbesserung der regionalen Wirtschaftsstruktur sowie der Agrarstruktur und des Küstenschutzes mit, wenn diese Aufgaben für die Gesamtheit bedeutsam sind, und trägt einen Teil der Kosten.' },
        { n: '91b', t: 'Wissenschaft, Forschung und Lehre, Bildungsvergleiche', s: 'Bund und Länder können bei der Förderung von Wissenschaft, Forschung und Lehre in Fällen überregionaler Bedeutung zusammenwirken – etwa bei der Exzellenzstrategie für Hochschulen. Sie können außerdem zur Feststellung der Leistungsfähigkeit des Bildungswesens im internationalen Vergleich zusammenarbeiten.' },
        { n: '91c', t: 'Informationstechnische Systeme', s: 'Bund und Länder können bei Planung, Errichtung und Betrieb ihrer IT-Systeme zusammenwirken. Der Bund regelt den übergreifenden Zugang zu Verwaltungsleistungen über einen gemeinsamen Portalverbund.' },
        { n: '91d', t: 'Leistungsvergleich', s: 'Bund und Länder können zur Feststellung und Förderung der Leistungsfähigkeit ihrer Verwaltungen Vergleichsstudien durchführen und veröffentlichen.' },
        { n: '91e', t: 'Grundsicherung für Arbeitsuchende', s: 'Bund, Länder und Kommunen arbeiten bei der Grundsicherung für Arbeitsuchende in der Regel in gemeinsamen Einrichtungen zusammen – den Jobcentern. Eine begrenzte Zahl von Gemeinden und Kreisen kann die Aufgaben auch allein wahrnehmen (Optionskommunen).' }
      ]
    },
    {
      nr: 'IX', titel: 'Die Rechtsprechung', bereich: 'Art. 92–104',
      intro: 'Die Rechtsprechung ist unabhängigen Richterinnen und Richtern anvertraut. Dieser Abschnitt enthält auch die sogenannten Justizgrundrechte, etwa den Anspruch auf rechtliches Gehör.',
      arts: [
        { n: '92', t: 'Gerichtsorganisation', s: 'Die rechtsprechende Gewalt ist den Richtern anvertraut. Sie wird durch das Bundesverfassungsgericht, die im Grundgesetz vorgesehenen Bundesgerichte und die Gerichte der Länder ausgeübt.', z: 'Die rechtsprechende Gewalt ist den Richtern anvertraut.' },
        { n: '93', t: 'Zuständigkeiten des Bundesverfassungsgerichts', s: 'Das Bundesverfassungsgericht entscheidet unter anderem über Streitigkeiten zwischen obersten Bundesorganen (Organstreit), über die Vereinbarkeit von Bundes- oder Landesrecht mit dem Grundgesetz (abstrakte Normenkontrolle), über Streitigkeiten zwischen Bund und Ländern, über Verfassungsbeschwerden jeder Person sowie von Gemeinden wegen Verletzung ihres Selbstverwaltungsrechts und in weiteren im Grundgesetz genannten Fällen.' },
        { n: '94', t: 'Zusammensetzung des Bundesverfassungsgerichts', s: 'Das Gericht besteht aus Bundesrichtern und anderen Mitgliedern – 16 Richterinnen und Richtern in zwei Senaten. Je die Hälfte wird vom Bundestag und vom Bundesrat gewählt. Die Amtszeit beträgt zwölf Jahre, eine Wiederwahl ist ausgeschlossen, die Altersgrenze liegt bei 68 Jahren; Richter bleiben bis zur Wahl ihrer Nachfolger im Amt. Diese Grundregeln stehen seit einer Änderung Ende 2024 im Grundgesetz, um das Gericht gegen politische Einflussnahme abzusichern. Kommt eine Wahl nicht rechtzeitig zustande, kann nach dem Bundesverfassungsgerichtsgesetz das jeweils andere Wahlorgan wählen.' },
        { n: '95', t: 'Oberste Gerichtshöfe des Bundes', s: 'Für die fünf Fachgerichtsbarkeiten errichtet der Bund oberste Gerichtshöfe: den Bundesgerichtshof (Karlsruhe) für Zivil- und Strafsachen, das Bundesverwaltungsgericht (Leipzig), den Bundesfinanzhof (München), das Bundesarbeitsgericht (Erfurt) und das Bundessozialgericht (Kassel). Zur Wahrung einer einheitlichen Rechtsprechung bilden sie einen Gemeinsamen Senat.' },
        { n: '96', t: 'Weitere Bundesgerichte', s: 'Der Bund kann für Angelegenheiten des gewerblichen Rechtsschutzes ein Bundesgericht errichten – das Bundespatentgericht in München. Außerdem können Wehrstrafgerichte (nur im Verteidigungsfall und für im Ausland eingesetzte Soldaten) und Dienstgerichte für Disziplinarverfahren errichtet werden.' },
        { n: '97', t: 'Unabhängigkeit der Richter', s: 'Richterinnen und Richter sind sachlich unabhängig und nur dem Gesetz unterworfen. Hauptamtlich und planmäßig endgültig angestellte Richter können gegen ihren Willen nur kraft richterlicher Entscheidung und aus gesetzlich bestimmten Gründen entlassen, abgesetzt oder versetzt werden (persönliche Unabhängigkeit).', z: 'Die Richter sind unabhängig und nur dem Gesetze unterworfen.' },
        { n: '98', t: 'Rechtsstellung der Richter, Richteranklage', s: 'Die Rechtsstellung der Bundesrichter wird durch Bundesgesetz, die der Landesrichter durch Landesgesetz geregelt. Verstößt ein Richter gegen die Grundsätze des Grundgesetzes, kann das Bundesverfassungsgericht auf Antrag des Bundestages mit Zwei-Drittel-Mehrheit seine Versetzung oder Entlassung anordnen. Über die Anstellung von Landesrichtern kann ein Richterwahlausschuss mitentscheiden.' },
        { n: '99', t: 'Verfassungsstreitigkeiten innerhalb eines Landes', s: 'Durch Landesgesetz kann die Entscheidung von Verfassungsstreitigkeiten innerhalb eines Landes dem Bundesverfassungsgericht zugewiesen werden. Heute haben alle Länder eigene Verfassungsgerichte.' },
        { n: '100', t: 'Konkrete Normenkontrolle', s: 'Hält ein Gericht ein Gesetz, auf das es bei seiner Entscheidung ankommt, für verfassungswidrig, muss es das Verfahren aussetzen und die Entscheidung des Bundesverfassungsgerichts einholen. Nur dieses darf ein Parlamentsgesetz verwerfen (Verwerfungsmonopol).' },
        { n: '101', t: 'Verbot von Ausnahmegerichten, gesetzlicher Richter', s: 'Ausnahmegerichte sind unzulässig. Niemand darf seinem gesetzlichen Richter entzogen werden – es muss im Voraus abstrakt feststehen, welches Gericht und welche Richter für einen Fall zuständig sind. Gerichte für besondere Sachgebiete sind nur durch Gesetz zulässig.' },
        { n: '102', t: 'Abschaffung der Todesstrafe', s: 'Die Todesstrafe ist in Deutschland seit 1949 abgeschafft.', z: 'Die Todesstrafe ist abgeschafft.' },
        { n: '103', t: 'Rechtliches Gehör, keine Strafe ohne Gesetz, Verbot der Doppelbestrafung', s: 'Vor Gericht hat jede Person Anspruch auf rechtliches Gehör. Eine Tat kann nur bestraft werden, wenn die Strafbarkeit gesetzlich bestimmt war, bevor die Tat begangen wurde (Rückwirkungsverbot). Niemand darf wegen derselben Tat auf Grund der allgemeinen Strafgesetze mehrmals bestraft werden.', z: 'Eine Tat kann nur bestraft werden, wenn die Strafbarkeit gesetzlich bestimmt war, bevor die Tat begangen wurde.' },
        { n: '104', t: 'Rechtsgarantien bei Freiheitsentziehung', s: 'Die Freiheit der Person darf nur auf Grund eines förmlichen Gesetzes beschränkt werden; festgehaltene Personen dürfen weder seelisch noch körperlich misshandelt werden. Über Zulässigkeit und Fortdauer einer Freiheitsentziehung entscheidet ein Richter. Die Polizei darf niemanden aus eigener Machtvollkommenheit länger als bis zum Ende des Tages nach dem Ergreifen festhalten. Von jeder richterlichen Entscheidung über eine Freiheitsentziehung ist ein Angehöriger oder eine Vertrauensperson zu benachrichtigen.' }
      ]
    },
    {
      nr: 'X', titel: 'Das Finanzwesen', bereich: 'Art. 104a–115',
      intro: 'Wer welche Ausgaben trägt, wem welche Steuern zustehen, wie der Finanzausgleich funktioniert und wie viele Schulden erlaubt sind – das Finanzverfassungsrecht ist einer der meistgeänderten Teile des Grundgesetzes.',
      arts: [
        { n: '104a', t: 'Ausgabenverteilung', s: 'Bund und Länder tragen die Ausgaben für ihre Aufgaben grundsätzlich selbst. Handeln die Länder im Auftrag des Bundes, trägt der Bund die Ausgaben. Bei Geldleistungsgesetzen des Bundes kann der Bund die Kosten ganz oder teilweise übernehmen; ab einer bestimmten Beteiligung wird aus der Länder- eine Auftragsverwaltung.' },
        { n: '104b', t: 'Finanzhilfen für Investitionen', s: 'Der Bund kann den Ländern Finanzhilfen für besonders bedeutsame Investitionen der Länder und Gemeinden gewähren, etwa zur Abwehr einer Störung des gesamtwirtschaftlichen Gleichgewichts oder zur Förderung des Wirtschaftswachstums. Bei Naturkatastrophen und außergewöhnlichen Notsituationen ist dies auch ohne Gesetzgebungsbefugnis des Bundes möglich.' },
        { n: '104c', t: 'Finanzhilfen für die Bildungsinfrastruktur', s: 'Der Bund kann den Ländern Finanzhilfen für gesamtstaatlich bedeutsame Investitionen und besondere Kosten in der kommunalen Bildungsinfrastruktur gewähren – Grundlage etwa des DigitalPakts Schule (seit 2019).' },
        { n: '104d', t: 'Finanzhilfen für den sozialen Wohnungsbau', s: 'Der Bund kann den Ländern Finanzhilfen für gesamtstaatlich bedeutsame Investitionen der Länder und Gemeinden im Bereich des sozialen Wohnungsbaus gewähren (seit 2019).' },
        { n: '105', t: 'Gesetzgebung über Steuern', s: 'Der Bund hat die ausschließliche Gesetzgebung über Zölle und Finanzmonopole und die konkurrierende über die meisten übrigen Steuern. Die Länder regeln örtliche Verbrauch- und Aufwandsteuern (z. B. Hundesteuer, Zweitwohnungsteuer) und bestimmen den Steuersatz der Grunderwerbsteuer. Steuergesetze, deren Aufkommen Ländern oder Gemeinden zufließt, brauchen die Zustimmung des Bundesrates.' },
        { n: '106', t: 'Verteilung des Steueraufkommens', s: 'Legt fest, welche Steuern dem Bund (z. B. Energiesteuer, Tabaksteuer, Solidaritätszuschlag), den Ländern (z. B. Erbschaftsteuer, Grunderwerbsteuer) und den Gemeinden (Grundsteuer, Gewerbesteuer) zustehen. Die großen Gemeinschaftsteuern – Einkommen-, Körperschaft- und Umsatzsteuer – werden zwischen den Ebenen aufgeteilt.' },
        { n: '106a', t: 'Mittel für den Personennahverkehr', s: 'Den Ländern steht ab 1996 für den öffentlichen Personennahverkehr ein Betrag aus dem Steueraufkommen des Bundes zu (Regionalisierungsmittel).' },
        { n: '106b', t: 'Ausgleich für die Kraftfahrzeugsteuer', s: 'Den Ländern steht ab 2009 ein Betrag aus dem Steueraufkommen des Bundes zu, weil die Kraftfahrzeugsteuer von den Ländern auf den Bund übergegangen ist.' },
        { n: '107', t: 'Finanzausgleich', s: 'Regelt die Verteilung des Länderanteils an den Gemeinschaftsteuern und sorgt für einen angemessenen Ausgleich der unterschiedlichen Finanzkraft der Länder. Seit 2020 geschieht dies vor allem über Zu- und Abschläge bei der Verteilung der Umsatzsteuer und über Ergänzungszuweisungen des Bundes; der frühere direkte Länderfinanzausgleich ist entfallen.' },
        { n: '108', t: 'Finanzverwaltung', s: 'Zölle, Finanzmonopole, bundesgesetzliche Verbrauchsteuern und EU-Abgaben werden durch Bundesfinanzbehörden verwaltet (z. B. Zoll). Die übrigen Steuern verwalten die Landesfinanzbehörden – die Finanzämter.' },
        { n: '109', t: 'Haushaltswirtschaft, Schuldenbremse', s: 'Bund und Länder sind in ihrer Haushaltswirtschaft selbstständig. Ihre Haushalte sind grundsätzlich ohne Einnahmen aus Krediten auszugleichen (Schuldenbremse, seit 2009). Ausnahmen gelten bei konjunkturellen Abschwüngen sowie bei Naturkatastrophen und außergewöhnlichen Notsituationen. Seit 2025 dürfen die Länder zusammen strukturell Kredite in Höhe von 0,35 Prozent der Wirtschaftsleistung aufnehmen.' },
        { n: '109a', t: 'Stabilitätsrat', s: 'Zur Vermeidung von Haushaltsnotlagen überwacht ein gemeinsames Gremium von Bund und Ländern, der Stabilitätsrat, fortlaufend die Haushaltswirtschaft und die Einhaltung der Schuldenregeln.' },
        { n: '110', t: 'Haushaltsplan des Bundes', s: 'Alle Einnahmen und Ausgaben des Bundes sind in den Haushaltsplan einzustellen, der für ein oder mehrere Jahre durch das Haushaltsgesetz festgestellt wird. Der Haushaltsplan ist in Einnahme und Ausgabe auszugleichen.' },
        { n: '111', t: 'Vorläufige Haushaltsführung', s: 'Ist bis zum Ende eines Jahres kein Haushalt für das Folgejahr beschlossen, darf die Bundesregierung bis zu dessen Inkrafttreten nur die Ausgaben leisten, die nötig sind, um Einrichtungen zu erhalten, gesetzliche Aufgaben und rechtliche Verpflichtungen zu erfüllen und begonnene Vorhaben fortzuführen.' },
        { n: '112', t: 'Über- und außerplanmäßige Ausgaben', s: 'Ausgaben über den Haushaltsplan hinaus brauchen die Zustimmung des Bundesfinanzministers. Sie ist nur bei einem unvorhergesehenen und unabweisbaren Bedürfnis zulässig.' },
        { n: '113', t: 'Ausgabenerhöhungen', s: 'Gesetze, die die Ausgaben erhöhen oder neue Ausgaben mit sich bringen oder Einnahmen mindern, brauchen die Zustimmung der Bundesregierung.' },
        { n: '114', t: 'Rechnungslegung, Bundesrechnungshof', s: 'Der Bundesfinanzminister legt jährlich Rechnung über Einnahmen, Ausgaben, Vermögen und Schulden. Der Bundesrechnungshof, dessen Mitglieder richterliche Unabhängigkeit besitzen, prüft Wirtschaftlichkeit und Ordnungsmäßigkeit der Haushalts- und Wirtschaftsführung des Bundes.' },
        { n: '115', t: 'Kreditaufnahme', s: 'Kredite und Bürgschaften brauchen eine gesetzliche Ermächtigung. Der Bund darf strukturell höchstens 0,35 Prozent der Wirtschaftsleistung an neuen Krediten aufnehmen; in Abschwüngen mehr, bei Naturkatastrophen und außergewöhnlichen Notsituationen mit Mehrheitsbeschluss des Bundestages und Tilgungsplan auch darüber hinaus. Seit März 2025 zählen Ausgaben für Verteidigung, Zivil- und Bevölkerungsschutz, Nachrichtendienste, Schutz der IT-Systeme und Hilfen für völkerrechtswidrig angegriffene Staaten, soweit sie ein Prozent der Wirtschaftsleistung übersteigen, nicht zur Schuldenbremse.' }
      ]
    },
    {
      nr: 'Xa', titel: 'Verteidigungsfall', bereich: 'Art. 115a–115l',
      intro: 'Die 1968 eingefügte „Notstandsverfassung“ regelt, wie der Staat bei einem bewaffneten Angriff handlungsfähig bleibt – ohne die Verfassung außer Kraft zu setzen.',
      arts: [
        { n: '115a', t: 'Feststellung des Verteidigungsfalls', s: 'Wird das Bundesgebiet mit Waffengewalt angegriffen oder droht ein solcher Angriff unmittelbar, stellt der Bundestag mit Zustimmung des Bundesrates auf Antrag der Bundesregierung den Verteidigungsfall fest – mit Zwei-Drittel-Mehrheit der abgegebenen Stimmen, mindestens der Mehrheit seiner Mitglieder. Ist das nicht rechtzeitig möglich, entscheidet der Gemeinsame Ausschuss.' },
        { n: '115b', t: 'Übergang der Befehlsgewalt', s: 'Mit der Verkündung des Verteidigungsfalls geht die Befehls- und Kommandogewalt über die Streitkräfte auf den Bundeskanzler über.' },
        { n: '115c', t: 'Erweiterte Gesetzgebungsbefugnis des Bundes', s: 'Der Bund hat im Verteidigungsfall die konkurrierende Gesetzgebung auch auf Gebieten, die sonst den Ländern zustehen. Unter anderem kann die Frist, in der Festgenommene einem Richter vorgeführt werden müssen, auf höchstens vier Tage verlängert werden.' },
        { n: '115d', t: 'Verkürztes Gesetzgebungsverfahren', s: 'Als dringlich bezeichnete Gesetzesvorlagen der Bundesregierung werden gleichzeitig dem Bundestag und dem Bundesrat zugeleitet und unverzüglich beraten.' },
        { n: '115e', t: 'Gemeinsamer Ausschuss als Notparlament', s: 'Stellt der Gemeinsame Ausschuss mit Zwei-Drittel-Mehrheit fest, dass dem rechtzeitigen Zusammentritt des Bundestages unüberwindliche Hindernisse entgegenstehen oder dieser nicht beschlussfähig ist, hat er die Stellung von Bundestag und Bundesrat. Das Grundgesetz darf er weder ändern noch außer Kraft setzen.' },
        { n: '115f', t: 'Einsatz der Bundespolizei, Weisungen', s: 'Die Bundesregierung kann im Verteidigungsfall die Bundespolizei im gesamten Bundesgebiet einsetzen und den Landesregierungen und -behörden Weisungen erteilen.' },
        { n: '115g', t: 'Stellung des Bundesverfassungsgerichts', s: 'Die verfassungsmäßige Stellung und die Aufgaben des Bundesverfassungsgerichts dürfen auch im Verteidigungsfall nicht beeinträchtigt werden.' },
        { n: '115h', t: 'Wahlperioden und Amtszeiten', s: 'Wahlperioden des Bundestages und der Landtage, die im Verteidigungsfall ablaufen, enden erst sechs Monate nach seinem Ende; die Amtszeit des Bundespräsidenten erst neun Monate danach. Eine Auflösung des Bundestages ist ausgeschlossen.' },
        { n: '115i', t: 'Maßnahmen der Landesregierungen', s: 'Sind die zuständigen Bundesorgane außerstande, die notwendigen Maßnahmen zur Abwehr der Gefahr zu treffen, können die Landesregierungen für ihr Gebiet selbst Maßnahmen treffen.' },
        { n: '115k', t: 'Geltungsdauer von Notstandsrecht', s: 'Gesetze für den Verteidigungsfall setzen entgegenstehendes Recht für die Dauer ihrer Anwendbarkeit außer Anwendung. Sie treten spätestens sechs Monate nach Beendigung des Verteidigungsfalls außer Kraft.' },
        { n: '115l', t: 'Aufhebung von Maßnahmen, Friedensschluss', s: 'Der Bundestag kann mit Zustimmung des Bundesrates jederzeit Gesetze des Gemeinsamen Ausschusses aufheben und den Verteidigungsfall für beendet erklären. Über den Friedensschluss wird durch Bundesgesetz entschieden.' }
      ]
    },
    {
      nr: 'XI', titel: 'Übergangs- und Schlussbestimmungen', bereich: 'Art. 116–146',
      intro: 'Viele dieser Artikel regeln den Übergang vom Deutschen Reich zur Bundesrepublik 1949 oder die Wiedervereinigung 1990 und sind heute größtenteils erledigt. Einige sind aber weiter wichtig – etwa die Übernahme der Kirchenartikel der Weimarer Verfassung oder das neue Sondervermögen von 2025.',
      arts: [
        { n: '116', t: 'Begriff „Deutscher“, Wiedereinbürgerung', s: 'Deutscher im Sinne des Grundgesetzes ist, wer die deutsche Staatsangehörigkeit besitzt oder als Flüchtling oder Vertriebener deutscher Volkszugehörigkeit oder als dessen Angehöriger Aufnahme im Gebiet des Deutschen Reiches in den Grenzen von 1937 gefunden hat. Wer zwischen 1933 und 1945 aus politischen, rassischen oder religiösen Gründen ausgebürgert wurde, und seine Nachkommen werden auf Antrag wieder eingebürgert.' },
        { n: '117', t: 'Übergangsregelung zu Art. 3 und 11', s: 'Recht, das der Gleichberechtigung von Mann und Frau widersprach, blieb höchstens bis zum 31. März 1953 in Kraft. Gesetze, die die Freizügigkeit wegen der Wohnungsnot beschränkten, blieben bis zu ihrer Aufhebung bestehen.' },
        { n: '118', t: 'Neugliederung im Südwesten', s: 'Die Neugliederung der Länder Baden, Württemberg-Baden und Württemberg-Hohenzollern konnte abweichend von Art. 29 geregelt werden. Nach einer Volksabstimmung entstand 1952 das Land Baden-Württemberg.' },
        { n: '118a', t: 'Berlin und Brandenburg', s: 'Berlin und Brandenburg können sich abweichend von Art. 29 unter Beteiligung ihrer Wahlberechtigten durch Vereinbarung zu einem Land zusammenschließen. Ein Fusionsversuch scheiterte 1996 an der Volksabstimmung in Brandenburg.' },
        { n: '119', t: 'Flüchtlinge und Vertriebene', s: 'In Angelegenheiten der Flüchtlinge und Vertriebenen, insbesondere ihrer Verteilung auf die Länder, konnte die Bundesregierung bis zu einer gesetzlichen Regelung Verordnungen erlassen (Übergangsvorschrift der Nachkriegszeit).' },
        { n: '120', t: 'Kriegsfolgelasten', s: 'Der Bund trägt die Aufwendungen für Besatzungskosten und die sonstigen inneren und äußeren Kriegsfolgelasten nach näherer Bestimmung von Bundesgesetzen, außerdem Zuschüsse zu den Lasten der Sozialversicherung.' },
        { n: '120a', t: 'Lastenausgleich', s: 'Gesetze zur Durchführung des Lastenausgleichs – des finanziellen Ausgleichs für Kriegs- und Vertreibungsschäden – können bestimmen, dass sie teils vom Bund, teils von den Ländern ausgeführt werden.' },
        { n: '121', t: 'Begriff „Mehrheit der Mitglieder“', s: 'Mehrheit der Mitglieder des Bundestages und der Bundesversammlung ist die Mehrheit ihrer gesetzlichen Mitgliederzahl.', z: 'Mehrheit der Mitglieder des Bundestages und der Bundesversammlung im Sinne dieses Grundgesetzes ist die Mehrheit ihrer gesetzlichen Mitgliederzahl.' },
        { n: '122', t: 'Übergang der Gesetzgebung', s: 'Ab dem Zusammentritt des Bundestages werden Gesetze ausschließlich von den im Grundgesetz bestimmten Organen beschlossen; bisherige gesetzgebende Einrichtungen erlöschen.' },
        { n: '123', t: 'Fortgeltung alten Rechts', s: 'Recht aus der Zeit vor dem Zusammentritt des Bundestages gilt fort, soweit es dem Grundgesetz nicht widerspricht. Das betrifft bis heute etwa Teile von BGB und Strafgesetzbuch, die aus der Kaiserzeit stammen.' },
        { n: '124', t: 'Altes Recht in ausschließlicher Zuständigkeit', s: 'Recht, das Gegenstände der ausschließlichen Gesetzgebung des Bundes betrifft, wurde innerhalb seines Geltungsbereichs Bundesrecht.' },
        { n: '125', t: 'Altes Recht in konkurrierender Zuständigkeit', s: 'Recht zu Gegenständen der konkurrierenden Gesetzgebung wurde Bundesrecht, soweit es in einer oder mehreren Besatzungszonen einheitlich galt oder früheres Reichsrecht abgeändert hatte.' },
        { n: '125a', t: 'Fortgeltung von Bundesrecht nach Kompetenzänderungen', s: 'Bundesrecht, das wegen späterer Änderungen der Zuständigkeiten nicht mehr als Bundesrecht erlassen werden könnte, gilt als Bundesrecht fort. Die Länder können es durch eigenes Recht ersetzen.' },
        { n: '125b', t: 'Fortgeltung früherer Rahmengesetze', s: 'Recht, das auf der Grundlage der früheren Rahmengesetzgebung (Art. 75 alte Fassung) erlassen wurde, gilt als Bundesrecht fort; die Länder können in bestimmten Bereichen abweichende Regelungen treffen.' },
        { n: '125c', t: 'Übergangsrecht nach der Föderalismusreform', s: 'Übergangsregeln für Bundesrecht, das auf Grundlage früherer Zuständigkeiten erlassen wurde, unter anderem zur Gemeindeverkehrsfinanzierung und zur sozialen Wohnraumförderung.' },
        { n: '126', t: 'Streit über das Fortgelten von Recht', s: 'Meinungsverschiedenheiten darüber, ob Recht als Bundesrecht fortgilt, entscheidet das Bundesverfassungsgericht.' },
        { n: '127', t: 'Recht des Vereinigten Wirtschaftsgebietes', s: 'Die Bundesregierung konnte mit Zustimmung der betroffenen Landesregierungen Recht der Verwaltung des Vereinigten Wirtschaftsgebietes (der britischen und amerikanischen Zone) innerhalb eines Jahres auch in Baden, Groß-Berlin, Rheinland-Pfalz und Württemberg-Hohenzollern in Kraft setzen.' },
        { n: '128', t: 'Fortbestehen von Weisungsrechten', s: 'Soweit fortgeltendes Recht Weisungsrechte vorsieht, bleiben diese bis zu einer anderweitigen gesetzlichen Regelung bestehen.' },
        { n: '129', t: 'Fortgeltung von Ermächtigungen', s: 'Ermächtigungen zum Erlass von Rechtsverordnungen oder Verwaltungsvorschriften in fortgeltendem Recht gehen auf die nun sachlich zuständigen Stellen über.' },
        { n: '130', t: 'Überleitung von Verwaltungseinrichtungen', s: 'Verwaltungsorgane und Einrichtungen der öffentlichen Verwaltung oder Rechtspflege, die nicht auf Landesrecht oder Staatsverträgen zwischen Ländern beruhen, unterstehen der Bundesregierung.' },
        { n: '131', t: 'Frühere Angehörige des öffentlichen Dienstes', s: 'Die Rechtsverhältnisse von Personen, die am 8. Mai 1945 im öffentlichen Dienst standen, ausgeschieden sind und noch nicht entsprechend verwendet wurden, werden durch Bundesgesetz geregelt.' },
        { n: '132', t: 'Übergangsvorschrift für Beamte und Richter', s: 'Erlaubte kurz nach Inkrafttreten des Grundgesetzes, Beamte und Richter in den Ruhestand zu versetzen, denen die persönliche oder fachliche Eignung für ihr Amt fehlte. Die Vorschrift ist heute gegenstandslos.' },
        { n: '133', t: 'Rechtsnachfolge des Vereinigten Wirtschaftsgebietes', s: 'Der Bund tritt in die Rechte und Pflichten der Verwaltung des Vereinigten Wirtschaftsgebietes ein.' },
        { n: '134', t: 'Reichsvermögen', s: 'Das Vermögen des Deutschen Reiches wird grundsätzlich Bundesvermögen; Vermögen, das für Aufgaben der Länder bestimmt war, geht auf die Länder über.' },
        { n: '135', t: 'Vermögen bei Gebietsänderungen', s: 'Regelt, wem das Vermögen von Ländern und Körperschaften zusteht, die nicht mehr bestehen oder deren Gebiet sich geändert hat – etwa des aufgelösten Landes Preußen.' },
        { n: '135a', t: 'Alte Verbindlichkeiten', s: 'Durch Bundesgesetz kann bestimmt werden, dass Verbindlichkeiten des Reiches, des ehemaligen Landes Preußen und bestimmter anderer Rechtsträger nicht oder nicht in voller Höhe zu erfüllen sind. Entsprechendes gilt für Verbindlichkeiten im Zusammenhang mit der DDR und der Wiedervereinigung.' },
        { n: '136', t: 'Erster Zusammentritt des Bundesrates', s: 'Der Bundesrat trat erstmals am Tag des ersten Zusammentritts des Bundestages zusammen – am 7. September 1949. Bis zur Wahl des ersten Bundespräsidenten nahm der Präsident des Bundesrates dessen Befugnisse wahr.' },
        { n: '137', t: 'Wählbarkeit von Beamten und Richtern', s: 'Die Wählbarkeit von Beamten, Angestellten des öffentlichen Dienstes, Berufssoldaten, Soldaten auf Zeit und Richtern in Bund, Ländern und Gemeinden kann gesetzlich beschränkt werden. Wer ein Mandat übernimmt, muss daher meist sein Amt ruhen lassen.' },
        { n: '138', t: 'Süddeutsches Notariat', s: 'Änderungen der Einrichtungen des Notariats in den Ländern Baden, Bayern, Württemberg-Baden und Württemberg-Hohenzollern bedürfen der Zustimmung der Regierungen dieser Länder.' },
        { n: '139', t: 'Entnazifizierungsvorschriften', s: 'Die zur „Befreiung des deutschen Volkes vom Nationalsozialismus und Militarismus“ erlassenen Rechtsvorschriften werden von den Bestimmungen des Grundgesetzes nicht berührt.' },
        { n: '140', t: 'Religionsgesellschaften (Weimarer Kirchenartikel)', s: 'Übernimmt die Artikel 136 bis 139 und 141 der Weimarer Reichsverfassung von 1919 als Teil des Grundgesetzes: Es gibt keine Staatskirche, Religionsgemeinschaften verwalten ihre Angelegenheiten selbst, als Körperschaften des öffentlichen Rechts dürfen sie Kirchensteuern erheben, Sonntage und staatlich anerkannte Feiertage sind geschützt, und Seelsorge in Krankenhäusern, Gefängnissen und im Heer ist zuzulassen.' },
        { n: '141', t: '„Bremer Klausel“', s: 'Die Pflicht, Religionsunterricht als ordentliches Lehrfach anzubieten (Art. 7 Abs. 3), gilt nicht in Ländern, in denen am 1. Januar 1949 eine andere landesrechtliche Regelung bestand – etwa in Bremen.' },
        { n: '142', t: 'Grundrechte in Landesverfassungen', s: 'Bestimmungen der Landesverfassungen bleiben in Kraft, soweit sie in Übereinstimmung mit den Artikeln 1 bis 18 des Grundgesetzes Grundrechte gewährleisten. Landesverfassungen können also zusätzliche Grundrechte enthalten.' },
        { n: '142a', t: '(aufgehoben)', s: 'Der Artikel betraf Verträge zur Europäischen Verteidigungsgemeinschaft der 1950er-Jahre und wurde 1968 aufgehoben.', rep: true },
        { n: '143', t: 'Übergangsrecht nach der Wiedervereinigung', s: 'Recht im Gebiet der ehemaligen DDR durfte übergangsweise – längstens bis Ende 1992, in bestimmten Bereichen bis Ende 1995 – vom Grundgesetz abweichen, soweit die unterschiedlichen Verhältnisse das erforderten. Enteignungen aus der Zeit der sowjetischen Besatzung (1945–1949), etwa die Bodenreform, werden nicht rückgängig gemacht.' },
        { n: '143a', t: 'Übergang bei den Bundeseisenbahnen', s: 'Übergangsregeln zur Umwandlung der Bundeseisenbahnen in Wirtschaftsunternehmen (Bahnreform 1994); dem Bund steht die ausschließliche Gesetzgebung über alle Angelegenheiten dieser Umwandlung zu.' },
        { n: '143b', t: 'Übergang bei der Deutschen Bundespost', s: 'Übergangsregeln zur Umwandlung des Sondervermögens Deutsche Bundespost in Unternehmen privater Rechtsform (Postreform 1994/95), unter anderem zum Schutz der Beamtinnen und Beamten der früheren Bundespost.' },
        { n: '143c', t: 'Kompensationsbeträge', s: 'Für den Wegfall der Gemeinschaftsaufgaben Ausbau und Neubau von Hochschulen sowie Bildungsplanung erhielten die Länder von 2007 bis Ende 2019 Ausgleichszahlungen aus dem Bundeshaushalt.' },
        { n: '143d', t: 'Übergang zur Schuldenbremse, Konsolidierungs- und Sanierungshilfen', s: 'Übergangsregeln zur Einführung der Schuldenbremse von 2009, Konsolidierungshilfen für Berlin, Bremen, das Saarland, Sachsen-Anhalt und Schleswig-Holstein bis 2019 sowie Sanierungshilfen für Bremen und das Saarland ab 2020.' },
        { n: '143e', t: 'Übergang bei den Bundesautobahnen', s: 'Regelte den Übergang der Autobahnen aus der Auftragsverwaltung der Länder in die Bundesverwaltung, die seit dem 1. Januar 2021 gilt.' },
        { n: '143f', t: 'Befristung der Finanzausgleichsregeln', s: 'Die Regeln der bundesstaatlichen Finanzbeziehungen treten außer Kraft, wenn nach dem 31. Dezember 2030 die Bundesregierung, der Bundestag oder mindestens drei Länder Neuverhandlungen verlangen und binnen fünf Jahren keine Neuregelung in Kraft tritt.' },
        { n: '143g', t: 'Übergang bei der Steuerverteilung', s: 'Für die Steuerverteilung, den Länderfinanzausgleich und die Bundesergänzungszuweisungen bis Ende 2019 galt Art. 107 in seiner alten Fassung weiter.' },
        { n: '143h', t: 'Sondervermögen Infrastruktur und Klimaneutralität', s: 'Seit März 2025 darf der Bund ein Sondervermögen mit eigener Kreditermächtigung von bis zu 500 Milliarden Euro errichten – für zusätzliche Investitionen in die Infrastruktur und zur Erreichung der Klimaneutralität bis 2045. 100 Milliarden Euro davon erhalten die Länder für Investitionen, 100 Milliarden Euro fließen in den Klima- und Transformationsfonds. Die Kredite zählen nicht zur Schuldenbremse.' },
        { n: '144', t: 'Annahme des Grundgesetzes', s: 'Das Grundgesetz bedurfte der Annahme durch die Volksvertretungen in zwei Dritteln der deutschen Länder, in denen es zunächst gelten sollte. Alle Landtage außer dem bayerischen stimmten 1949 zu; Bayern erkannte die Geltung aber an.' },
        { n: '145', t: 'Verkündung', s: 'Der Parlamentarische Rat stellte das Grundgesetz am 23. Mai 1949 in öffentlicher Sitzung fest, fertigte es aus und verkündete es. Es trat mit Ablauf dieses Tages in Kraft. Der 23. Mai gilt seitdem als Geburtstag der Bundesrepublik.' },
        { n: '146', t: 'Geltungsdauer', s: 'Seit der Wiedervereinigung gilt das Grundgesetz für das gesamte deutsche Volk. Es verliert seine Gültigkeit erst, wenn eine vom deutschen Volk in freier Entscheidung beschlossene Verfassung in Kraft tritt.', z: 'Dieses Grundgesetz, das nach Vollendung der Einheit und Freiheit Deutschlands für das gesamte deutsche Volk gilt, verliert seine Gültigkeit an dem Tage, an dem eine Verfassung in Kraft tritt, die von dem deutschen Volke in freier Entscheidung beschlossen worden ist.' }
      ]
    }
  ]
};
